$ErrorActionPreference='Stop'
$ProgressPreference='SilentlyContinue'
[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
function Verify-File([string]$Path,[string]$Sha){
 if((Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $Sha){throw ('Changed input: '+$Path)}
}
function Run-Git([string[]]$GitArguments){
 $psi=New-Object Diagnostics.ProcessStartInfo
 $psi.FileName='git.exe';$psi.UseShellExecute=$false;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true
 $psi.Arguments=($GitArguments|ForEach-Object {'"'+$_.Replace('"','\"')+'"'}) -join ' '
 $p=New-Object Diagnostics.Process;$p.StartInfo=$psi
 if(-not $p.Start()){throw 'Git did not start'}
 $outTask=$p.StandardOutput.ReadToEndAsync();$errTask=$p.StandardError.ReadToEndAsync()
 if(-not $p.WaitForExit(30000)){try{$p.Kill()}catch{};throw 'Git timeout'}
 $stdout=$outTask.GetAwaiter().GetResult();$stderr=$errTask.GetAwaiter().GetResult()
 if($p.ExitCode -ne 0){throw ('Git failed: '+$stderr)}
 return $stdout.Trim()
}
$manifest='D:/projects/cold-prefill-tail-server-source-r2.json'
$bindingPath='D:/projects/cold-prefill-tail-server-build-binding-r2.json'
$binding=[IO.File]::ReadAllText($bindingPath)|ConvertFrom-Json
Verify-File $manifest $binding.source_manifest_sha256
$m=[IO.File]::ReadAllText($manifest)|ConvertFrom-Json
Verify-File $PSCommandPath $m.script_sha256
$repo=$m.repo.Replace('/','\')
$sha=$m.source_commit
if(-not(Test-Path -LiteralPath $repo -PathType Container)){throw 'The same-source whole build must create this checkout first'}
$head=Run-Git -GitArguments @('-C',$repo,'rev-parse','HEAD')
if($head -ne $sha){throw 'Source commit mismatch'}
$dirty=Run-Git -GitArguments @('-C',$repo,'status','--porcelain')
if($dirty){throw 'Dirty source checkout'}
foreach($item in $m.source_sha256.PSObject.Properties){Verify-File (Join-Path $repo $item.Name) $item.Value}
$priorPath=Join-Path $repo ('build/'+$m.whole_build_directory+'/run-record.json')
Verify-File $priorPath $binding.whole_build_run_sha256
$prior=[IO.File]::ReadAllText($priorPath)|ConvertFrom-Json
if($prior.reason -ne 'completed' -or $prior.exit_code -ne 0 -or -not $prior.host_checks_pass -or @($prior.after_processes).Count -ne 0 -or $prior.spec.repo_commit -ne $sha){throw 'The whole build or cleanup did not pass'}
foreach($check in $prior.host_checks.PSObject.Properties){if(-not $check.Value){throw 'A prior host check failed'}}
$build=Join-Path $repo ('build/'+$m.build_directory)
$out=Join-Path $repo ('build/'+$m.run_directory)
$specPath=$out+'.json'
foreach($path in @($build,$out,$specPath)){if(Test-Path -LiteralPath $path){throw ('Existing evidence: '+$path)}}
$inputs=@()
foreach($entry in $m.source_sha256.PSObject.Properties){$inputs+=@{file=$entry.Name;sha256=$entry.Value}}
$spec=[ordered]@{
 executable='C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe'
 arguments=@('-NoLogo','-NoProfile','-NonInteractive','-File',(Join-Path $repo 'scripts/baiying_build_qrt_server.ps1'),'-OutDir',$build,'-TimeoutSeconds',[string]$m.compile_and_test_timeout_seconds)
 working_directory=$repo;repo_commit=$sha;source_inputs=$inputs
 command_file=$PSCommandPath;command_file_sha256=$m.script_sha256
 source_manifest_sha256=$binding.source_manifest_sha256
 whole_build_run_sha256=$binding.whole_build_run_sha256
 model='none; Rust server and statically linked C core build and unit tests'
 model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false
 purpose='Build the HTTP server with the same cold-tail C core as the current product CLI; run all server unit tests. Final-artifact inference remains separate.'
}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts/baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $m.native_timeout_seconds|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass -or @($r.after_processes).Count -ne 0){throw 'Native server build or cleanup failed'}
foreach($check in $r.host_checks.PSObject.Properties){if(-not $check.Value){throw 'A server build host check failed'}}
$meta=[IO.File]::ReadAllText((Join-Path $build 'build-provenance.json'))|ConvertFrom-Json
if($meta.repo_commit -ne $sha -or $meta.dirty_tree -or -not $meta.tests_run -or $meta.validate_only -or $meta.timeout_seconds -ne $m.compile_and_test_timeout_seconds){throw 'Server build provenance mismatch'}
if($meta.context_limits_header_sha256 -ne $m.source_sha256.'native/src/qrt_context_limits.h'){throw 'Server context header mismatch'}
Verify-File $meta.executable $meta.executable_sha256
$stdout=[IO.File]::ReadAllText((Join-Path $build 'build.stdout.txt'))
if(-not $stdout.Contains(('test result: ok. '+$m.expected_library_tests+' passed; 0 failed;'))){throw 'Expected complete server unit-test result is missing'}
foreach($item in $m.source_sha256.PSObject.Properties){Verify-File (Join-Path $repo $item.Name) $item.Value}
